S = "Hakeem Force Academy"
QS = [
(S, "Between whom was the Ghazwa (Battle) of Badr fought?", ["The Muslims of Madinah and the Quraish of Makkah", "The Muslims and the Jews of Khyber", "The Muslims and the Byzantine army", "The Muslims and the tribe of Thaqif at Taif"], 0, "Badr was fought in 2 AH between the small Muslim army led by the Holy Prophet (PBUH) and the much larger army of the Quraish of Makkah.", "Badr is called Yaum-ul-Furqan, the day that separated right from wrong.", [1833]),
(S, "Near which city is the mountain where the Battle of Uhud was fought?", ["Madinah", "Makkah", "Taif", "Khyber"], 0, "The Battle of Uhud was fought at the foot of Mount Uhud, a few kilometres north of Madinah.", "The battle took place in 3 AH between the Muslims and the Quraish of Makkah.", [2648]),
(S, "Who was the founder of the USSR (Soviet Union)?", ["Vladimir Lenin", "Joseph Stalin", "Leon Trotsky", "Nikita Khrushchev"], 0, "Vladimir Lenin led the Bolshevik Revolution of 1917 and headed the new state when the USSR was formally created in 1922.", "Joseph Stalin ruled the USSR after Lenin's death in 1924.", [1470]),
(S, "Which is the fourth source of Islamic law (Shariah) in the usual order?", ["Qiyas (analogical reasoning)", "Hadith", "Ijma (consensus)", "The Holy Quran"], 0, "The four sources in order are the Holy Quran, the Sunnah (Hadith), Ijma (consensus of scholars) and Qiyas (analogy).", "Hanafi fiqh, followed by most Pakistanis, accepts all four sources.", [594]),
(S, "What kind of fraction is 9/3?", ["Improper fraction", "Proper fraction", "Mixed fraction", "Unit fraction"], 0, "In 9/3 the numerator 9 is larger than the denominator 3, so it is an improper fraction. It simplifies to the whole number 3.", "A proper fraction has a numerator smaller than its denominator, such as 5/7.", [1607, 1608]),
(S, "Which fraction comes next in the series: 3/5, 5/8, 8/12, 12/17, ?", ["17/23", "17/22", "16/22", "18/24"], 0, "Numerators are 3, 5, 8, 12, 17 with differences 2, 3, 4, 5, so the next is 17. Each denominator equals the next numerator, and the denominators 5, 8, 12, 17 continue with 17+6 = 23.", "Each fraction's numerator equals the previous fraction's denominator.", [4585]),
(S, "What is the capital of France?", ["Lyon", "Paris", "Marseille", "Nice"], 1, "Paris, on the River Seine, is the capital and largest city of France.", "The Eiffel Tower is in Paris.", [583]),
(S, "What is the currency of France?", ["Euro", "Franc", "Pound", "Swiss franc"], 0, "France uses the euro, which replaced the French franc in 2002.", "The euro is shared by most countries of the European Union eurozone.", [3563]),
(S, "Who is the Prime Minister of France as of October 2026?", ["Francois Bayrou", "Elisabeth Borne", "Sebastien Lecornu", "Michel Barnier"], 2, "Sebastien Lecornu was appointed Prime Minister in September 2025 and reappointed in October 2025, and was still in office in October 2026.", "Elisabeth Borne (2022-2024), whom candidates wrote in 2022, was later followed by Attal, Barnier and Bayrou; Emmanuel Macron is the President, not the PM.", [5165, 97, 110]),
(S, "Which party formed the government in the North-West Frontier Province (now KPK) just before the creation of Pakistan in 1947?", ["Indian National Congress (Dr Khan Sahib)", "All India Muslim League", "Unionist Party", "Khaksar Tehrik"], 0, "After the 1946 elections the Congress under Dr Khan Sahib formed the ministry in the NWFP, which stayed in office until it was dismissed in August 1947.", "The people of the NWFP voted for Pakistan in the referendum of July 1947.", [4811]),
(S, "If the first day of a month is Friday, which day will the 17th be?", ["Sunday", "Saturday", "Monday", "Friday"], 0, "The 15th is 14 days (two full weeks) after the 1st, so it is also a Friday. The 17th is two days later, a Sunday.", "A week has 7 days, so dates 7 apart fall on the same weekday.", [2421]),
(S, "Change the narration (direct speech) of: He bade farewell to his friends.", ["He said to his friends, \"Good-bye.\"", "He said to his friends that good-bye.", "He told his friends, \"Farewell to you.\"", "He asked his friends, \"Good-bye?\""], 0, "To bid farewell means to say good-bye, so in direct speech it becomes: He said to his friends, \"Good-bye.\"", "Similar idioms: bade welcome becomes said, \"Welcome\", and wished becomes said, \"Good luck.\"", [1877]),
(S, "The Friendship Gate (Bab-e-Dosti) at Chaman is a border crossing between which two countries?", ["Pakistan and Afghanistan", "Pakistan and Iran", "Pakistan and India", "Pakistan and China"], 0, "The Friendship Gate stands at Chaman in Balochistan on the Pakistan-Afghanistan border.", "It is on Pakistan's western border, the Durand Line, opposite Spin Boldak in Afghanistan.", [2024, 3026, 3027]),
(S, "A plane uses 160 gallons of fuel to cover 330 nautical miles. About how many gallons will it use to cover 700 nautical miles?", ["About 339 gallons", "About 320 gallons", "About 350 gallons", "About 300 gallons"], 0, "Fuel per mile is 160 divided by 330, and 700 times 160 divided by 330 is 112000 divided by 330, which is about 339.4 gallons.", "Fuel used is directly proportional to distance when the rate is constant.", [740]),
(S, "What is the full form of PIA?", ["Pakistan International Airlines", "Pakistan Internal Airways", "Pakistan Intercity Airlines", "Pakistan International Aviation"], 0, "PIA stands for Pakistan International Airlines, the national flag carrier of Pakistan.", "PIA began as Orient Airways in 1946 and took its present name in 1955.", [3626]),
(S, "In which galaxy does the Earth lie?", ["Andromeda", "Milky Way", "Triangulum", "Whirlpool"], 1, "Our solar system and the Earth lie in the Milky Way galaxy, a barred spiral galaxy.", "The nearest large galaxy to the Milky Way is Andromeda.", [2590, 2591, 2592, 3806]),
(S, "In which city were the Olympic Games named Tokyo 2020 held?", ["Tokyo", "Beijing", "Paris", "Rio de Janeiro"], 0, "The 2020 Summer Olympics were awarded to Tokyo, Japan. Because of COVID-19 they were postponed and held in Tokyo from July to August 2021.", "Paris hosted the 2024 Summer Olympics.", [2561]),
(S, "The ancient region of Gandhara lay mainly between which two modern cities?", ["Peshawar and Rawalpindi", "Lahore and Multan", "Quetta and Karachi", "Sukkur and Hyderabad"], 0, "Gandhara covered the Peshawar valley and the Potohar plateau around Taxila, roughly from Peshawar to Rawalpindi in north-west Pakistan.", "Sources differ on exact limits, but Taxila and Peshawar are its best-known centres.", [501, 4364]),
(S, "What is the name of the keeper (gatekeeper) of Hell (Jahannam)?", ["Malik", "Ridwan", "Jibrail", "Israfil"], 0, "The angel Malik is named in the Quran (Surah Az-Zukhruf) as the keeper of Hell.", "Ridwan is the angel in charge of Paradise.", [3819, 3820, 5154, 5155]),
(S, "How many doors (gates) does the Holy Kaaba have?", ["One", "Two", "Four", "Seven"], 0, "The Kaaba has a single door, on its north-east wall, about two metres above ground level.", "The door is made of gold-plated material and is opened only on special occasions.", [2153]),
(S, "Who served as both Governor General and Prime Minister of Pakistan?", ["Khawaja Nazimuddin", "Ghulam Muhammad", "Iskander Mirza", "Liaquat Ali Khan"], 0, "Khawaja Nazimuddin was Governor General from 1948 to 1951 and then Prime Minister from 1951 to 1953.", "He became Governor General after the death of Quaid-e-Azam.", [5297]),
]
